private val JSONP_CALLBACK_PARAM = "callback"

  @BeanProperty
  var jsonpCallbackName: String = JSONP_CALLBACK_PARAM

  override def renderMergedOutputModel(model: util.Map[String, _], request: HttpServletRequest, response: HttpServletResponse): Unit = {
    val callback = request.getParameter(jsonpCallbackName)
    if (callback == null) {
      super.renderMergedOutputModel(model, request, response)
    } else {
      response.setContentType(getContentType)
      val json = JsonUtils.toJson(model)
      val paddedJson = new JSONPObject(callback, json)
      val writer = response.getWriter
      writer.write(JsonUtils.toJson(paddedJson))
      writer.flush()
    }
  }
}

