  def deleteTopic(topic: String) {
    if (!zkClient.topicExists(topic))
      throw new UnknownTopicOrPartitionException(s"Topic '$topic' not found.")

    info(s"Deleting topic $topic")
    zkClient.deleteTopic(topic)
  }

