    case L.HLIGD  ⇒ Some(HLIGD.geq(list1, list2))
    case L.EMGM   ⇒ Some(EMGM.geq(list1, list2))
    case _        ⇒ None
  }

  def min(lib: L.Value) = lib match {
    case L.None      ⇒ Some(1)
