    case L.HLIGD     ⇒ Some(HLIGD.foldl(list2)(Int.MaxValue)(scala.math.min))
    case L.EMGM      ⇒ Some(EMGM.min(list2))
    case L.Direct    ⇒ Some(list2.foldLeft(Int.MaxValue)(scala.math.min))
    case L.Shapeless ⇒ Some(ShapelessFun.min(list2))
    case _           ⇒ None
  }
