  private var lastResult: Option[AnyRef] = None;

  private def eval(code: String): SimpleEvaluationObject = {
    val result = repl.interpret(code);
    result match {
      case Success =>
        val last = repl.lastRequest.get.expr.eval();
        lastResult = Option(last);
