      override val ddl = schema.reduceLeft(_ ++ _)
      override def entityToEntityClass(entityName: String, cols: Seq[ColumnDef]) = {
        val className = entityName.toLowerCase.toCamelCase
        val colsWithEntity = cols.map(c => c.copy(name = c.name.toCamelCase))
        val companionCols = colsWithEntity.map(c => s"val ${c.name}: ${c.typeString} = ???")
        val companionBody = if (companionCols.isEmpty) "" else s"object ${className} {\n  ${companionCols.mkString("\n  ")}\n}"
        val entityBody = s"case class ${className}(${colsWithEntity.map(c => s"${c.name}: ${c.typeString}").mkString(", ")})\n$companionBody"
        entityBody
      }
    }

